using static StrataLint.Scribe.DefinitionDsl;

namespace StrataLint.Scribe.Blueprint.D5.S3.Combinatorics.Circle.FourNegative;

internal sealed class FirstPeakSaddleDocument : IScribeDocumentDefinition
{
    public DocumentDefinition Create() => DocumentDefinition.Create(ScribeNode.Create(
        "One actual physical ear in every strict saddle chamber",
        H("Complete source, physical construction and arithmetic join"),
        Blocks(Describe.Lean(DescribeId.Create("actual-source-first-peak-saddle-joint-lift"),
            DeclarationHandle.Create("D5/S3/Combinatorics/Circle/FourNegative/FirstPeakSaddle.actualSource_first_peak_saddle_joint_lift"),
            H("All natural a>b>d>c>=2"),
            StatementSource.WithoutFormula(), AssessedProvenance.FromRepo(),
            Blocks(
                Paragraph(Text("The strict-saddle construction joins six native arithmetic choices to one physical reconstruction. The declaration handle names the complete eight-binder endpoint itself, with its closed dependent-family Reg binding. Its arithmetic consists of 517 polynomial margins across 63 unbounded charts. The physical reconstruction retains the original labels, a single literal insertion cut, every natural prefix and both zero totals. Verification status and source provenance are supplied by the canonical Lean report and emitted declaration binding.")),
                Paragraph(Text("The exact final telescope is (a b c d:Nat)(hc:2<=c)(hcd:c<d)(hdb:d<b)(hba:b<a): eight binders. There is no upper bound on any exponent and no hypothesis a<=d+3, a<=c+d, arithmetic certificate or mask feasibility. Put k=a+b+c+d and alpha=1+2^a+2^(a+b)+2^(a+b+c). The conclusion is one sigma:List(Fin k), one natural cut<=k, OriginalOrder k alpha sigma and OriginalOrder (k+1) (2*alpha) (earWord k sigma cut). OriginalOrder retains every original physical occurrence, every natural take-prefix, and the exact zero final total in each row. Equal numerical weights never identify labels.")),
                Paragraph(Text("Use x=2^a,y=2^b,z=2^c,t=2^d,N=xyzt-1,Q=2N+1,D=y(z+1)+1. Then A=xD+1=alpha, B=xt(y+1)+t+1, L=xzt+zt+z+1, M=tyz+D, Bn=2B-1, Ln=2L-z-1 and Mn=2M-D. The actual old value at label i is centered N (2^i*A); the enlarged value at each old label i is centered Q (2^i*(2A)). PacketNormalForm.Source.chain_values, through MaxPlusTwo.SourceTable.source_table, gives these literal centered residues. No parallel abstract source system or external source certificate is introduced.")),
                Paragraph(Text("The source module writes all eight exact recurrences: tA=N+B, zB=N+L, yL=N+M, xM=N+A and t(2A)=Q+Bn, zBn=Q+Ln, yLn=Q+Mn, xMn=Q+A. Each identity is expanded by ring at all four native chain indices. The old bases and modulus are odd. The new successors Bn,Ln,Mn,A are odd; the first new positive base 2A is even. Reused positive base bounds, these parity facts and the nonnegative charge give the explicit successor bounds from 1 to modulus-2. The existing source table therefore applies its exact centered ladder reductions; the largest positive term is (modulus+successor)/4 and lies at most at the centered half bound.")),
                Paragraph(Text("There are four actual chains, U,V,W,X, of respective lengths d,c,b,a at offsets 0,d,d+c,d+c+b. Their positive local exponents are exactly e<length-1, with old bases A,B,L,M and enlarged bases 2A,Bn,Ln,Mn. Each next physical label is a separate negative terminal, of value -(N-successor)/2 in the old row and -(Q-newSuccessor)/2 in the enlarged row. The four terminal labels are d-1,d+c-1,d+c+b-1,k-1. The exact new value at literal label k, hence at Fin.last k, is A. The old chain totals telescope to zero; the enlarged old-label total is -A and the fresh label adds A. The scripts reuse source_totals and source_zero for both exact totals.")),
                Paragraph(Text("The sole private arithmetic interface is JointChoice a b c d. It contains natural s,r,h,v, the native bounds 1<=r<=s<=2^(a-1), v<2^(d-1), h<2^(b-1), the bit inclusion (r-1).testBit e implies (s-1).testBit e for every e<a-1, and twelve nonnegative paired seam margins. Its field order is s,r,h,v. It makes u=r-1 a physical submask of m=s-1; the W split has w=0. This interface is consumed only by the private physical reconstruction. Native.native_choice_exists constructs this interface in all six regions; the public endpoint consumes that existence and actualSource_of_nativeChoice without adding a premise.")),
                Paragraph(Text("The six disjoint arithmetic regions of the supplied unrestricted ordinary candidate are: (I) b>c+d; (IIa) b<=c+d,c>=3,a<c+d; (IIb) b<=c+d,c>=3,a=c+d; (IIc) b<=c+d,c>=3,a>c+d; (IIIa) b<=c+d,c=2,a<=d+3; (IIIb) b<=c+d,c=2,a>=d+4. These cases exhaust every strict saddle since c=2 or c>=3, b lies on one side of c+d, and the remaining comparison is exhaustive over natural a. There is no finite cutoff. Only the internal c=2 branch split mentions d+3; it is not a hypothesis of the theorem or of the generic physical constructor.")),
                Paragraph(Text("Region I consumes HighMiddle.high_middle_choice_exists, with 12 exact unbounded polynomial margins. Regions IIa and IIb consume GeneralArithmetic.parameterChoice, whose cyclic strict and residue-boundary equality constructions contain 28 and 48 margins. Region IIc consumes HalfStep.half_step_choice_exists and all 72 half-step margins. Region IIIa consumes the original small-c2 arithmetic_choice_exists and its 285 direct margins. Region IIIb consumes QuarterStep.quarter_step_choice_exists and all 72 quarter-step margins. The original polynomial ring/positivity terms are retained as Lean source; no JSON verdict or sampled parameter bound is a premise. There are 517 margins across 63 charts in total, with unbounded polynomial parameter families and three explicit t=8 small-c2 exceptions.")),
                Paragraph(Text("The private conversions prove that all source constants D,A,B,L,M,Bn,Ln,Mn and all gate coordinates agree, respecting diagonal argument order x,y,z,t versus physical t,z,x,y and physical field order s,r,h,v. rectangle_agrees proves by fin_cases and ring that the directly written H equals E+rD-h(z+1) when s=q+r. gate_agrees proves the entire Fin12 gate equality. GeneralArithmetic.rectangle_to_twelve now assumes z>=4, with the factored positivity proof and both third-gate slack identities retained; high-middle and quarter-c2 consume this version through remaining_joint_choice. Native exponent identities derive q=x/2-g and the h capacity from the native bounds. No gate is assumed for those branches.")),
                Paragraph(Text("The direct small-c2 Choice is deliberately converted separately. Its Fin19 contains the same first twelve actual paired gates followed by seven capacity margins. small_c2_joint_choice proves their equality to the physical Fin12 gates at z=4 and copies the actual native bounds and submask. All-one-mask branches, including t=8 and both phases with s=x/2, and the even-s/r=1-or-2 branches are retained. This branch may have r>g and need not use fixed q; no grain bound, reserve anchor or fixed-q condition is added to it. Small-c2 and quarter-step share the single private ModTen phase owner.")),
                Paragraph(Text("Decode masks by the existing chamberLabels into original occurrence indices. Let U,V,W,X denote their full positive sets, Uv the U mask v, Wh the W mask h, Xm the X mask s-1 and Xu the X mask r-1. Use P=(U minus Uv) union Wh union (X minus Xm), Qbank=Xm minus Xu, R=Uv union V union Xu, and G=W minus Wh. Submask inclusion proves Xu is contained in Xm. The intervals for the four chains and the exact native full-mask identity prove disjointness and exhaustion, including every one of the c-1 V-positive occurrences. Their proof uses c-1 as the V length for arbitrary c, rather than the c=2 constant 1. No label is dropped when it has the same numerical source value as another label.")),
                Paragraph(Text("Exact geometric sums give P old mass (t/2-1-v)A+hL+(x/2-s)M, Qbank mass (s-r)M and R mass vA+(z/2-1)B+(r-1)M. The enlarged masses use the same sets with A replaced by 2A, B by Bn, L by Ln and M by Mn. The decoder permutation and the geometric mass theorem are reused from Chambers.Masks; the source is the literal oldValue/newValue functions. Native bounds justify natural subtraction casts before integer mass algebra. The unused fourth bank is the exact finite-set complement, proved equal to W minus Wh.")),
                Paragraph(Text("Append the four distinct terminals in the order X,V,U,W. The natural word is P,k-1,Qbank,d+c-1,R,d-1,G,d+c+b-1. The existing four_perm proves it permutes List.range k. Map it through the established label k map to obtain sigma. Let first=P.toList++[k-1] and set cut=first.length. The permutation length gives cut<=k. Insert the literal new label k immediately after first, giving P,k-1,k,Qbank,d+c-1,R,d-1,G,d+c+b-1. marked_word proves that its Fin-labelled version is precisely earWord k sigma cut, with Fin.last k at this same cut and every original label cast by Fin.castSucc.")),
                Paragraph(Text("The old post-terminal seams are S1=(t/2-v)A-sM+hL, S2=(B+L)/2-vA-rM+hL, S3=(h+1)L-M, then zero. The enlarged seams are K1=(t-1-2v)A-sMn+hLn, K2=(Bn+Ln)/2-2vA-rMn+hLn, K3=(h+1)Ln-Mn, then zero. K1 is measured before insertion; K2 and K3 include the fresh A. The six doubled seams are E1=2S1,F1=2K1,E2=2S2,F2=2K2,E3=2S3,F3=2K3. Gate indices 0 through 11 are E1,A-1-E1,F1,A-1-F1,E2,L-1-E2,F2,Ln-1-F2,E3,B-1-E3,F3,Bn-1-F3. These formulas, their argument order t,z,x,y,s,r,h,v and all signs are the integration contract.")),
                Paragraph(Text("The source recurrences, terminal parity and exact bank masses give all six displayed seam equalities. Each gate pair gives a nonnegative seam and its successor bound. Before a negative terminal the peak is the following seam plus (modulus-successor)/2, so the old peak is at most N/2 and the enlarged peak at most N. All bank entries are positive actual source terms. Treat the inserted A as the first positive entry of the second enlarged bank. four_strip then bounds every intermediate prefix between its starting seam and its peak, including the insertion itself. The final W terminal uses the actual source bound and the exact zero total. Through inStrip_prefix and lift_order this covers every natural take, including empty, complete and overlong takes; no shortened prefix scope is used.")),
                Paragraph(Text("The exact dependent-family Reg mirror has parameters (a,b,c,d), all four original inequalities, coordinates [0,1,2,3], two roles Bool.false/Bool.true and both actual OriginalOrder readouts. Its state is the natural seed and its outputs retain the dependent Fin-labelled lists. The law reconstructs the entire eight-binder endpoint, including the shared sigma and cut, and source_equivalence is a definitional equivalence of those complete statements. Whole-family variation replaces both readouts by False; deleting either role gives sensitivity while fixing the other role and the empty anchor family. Actual observational dependence uses (a,b,c,d)=(5,4,2,3): old seed 0 versus 2 differs on the identity word, whose length-13 old prefix at seed 2 is negative; enlarged seed 0 versus 1 differs on earWord 14 identityWord 0, whose first fresh value at seed 1 is negative. These are proof scripts about the actual readouts, not hypothetical readout variation alone.")),
                Paragraph(Text("The Reg readout uses the existing enrolled DependentFamily.realize template from Reg.Support.DependentFamily. It carries the complete source_registration proof, the exact full public theorem, variation, sensitivity, dependence, sourceSelection and continuation unknown; familyRecord is none for the direct source realization. The two source paths have exactly eight leading body steps and select the old occurrence before the enlarged occurrence. The closed audit directly targets actualSource_first_peak_saddle_joint_lift, and source_registration reconstructs precisely that complete source type. No endpoint proof argument remains. The old readout precedes the enlarged readout; both selector paths begin with exactly eight body steps. Unknown continuation records a residual without claiming undecidability, inexhaustibility or any missing theorem.")),
                Paragraph(Text("Attribution and reuse: the ordinary arithmetic candidate and the completed physical draft are supplied by the caller. The construction uses standard dyadic masks, finite-set partitions, geometric sums and positive-block prefix bounds. SourceTable/PacketNormalForm.Source provide actual centering, signs and totals; Chambers.Masks supplies chamberLabels and its exact masses; Descending.Endpoint supplies half_power; AscendingD2.Schedule supplies four_perm/four_strip; ThreeNegativeEqualOuterJointLift supplies label/lift_order/marked_word; RunFirstEarTransport supplies earWord. All mathematical helpers are private and consumed by this one public theorem. The diagonal source is split into Certificates, CyclicArithmetic and GeneralArithmetic; direct small-c2 into Certificates and Arithmetic; shared phases into ModTen. The remaining seven arithmetic modules and Structure, Source, Physical and Native form the complete import graph. Every D5 module has at most 1000 physical lines. No obsolete grain-four/eight table or restricted public endpoint is installed.")),
                Paragraph(Text("The exact scope is the strict-saddle family a>b>d>c>=2. It includes every exponent size and uses no external feasibility or polynomial certificate premise. Unrestricted four-gap J and Circle Conjecture 3.1 remain open beyond this family. The surrounding problem is attributed to Damasdi, Frankl, Pach and Palvolgyi, Monochromatic configurations on a circle, arXiv:2504.10687v2; this construction makes no literature-novelty claim."))),
            DescribeRole.Theorem)), []));
}
